@Test
void confirmingSendsTheReceiptByEmail() {
    Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.NON_REFUNDABLE));

    service.confirm(reservation.id());

    assertEquals(ReservationStatus.CONFIRMED, service.find(reservation.id()).status());
    List<Message> sent = sentMessages.all();
    assertEquals(2, sent.size());
    Message mainMessage = sent.get(0);
    Message archiveCopy = sent.get(1);
    assertEquals("EMAIL", mainMessage.channel());
    assertEquals("ana@example.com", mainMessage.to());
    assertEquals("Reserva confirmada - Pousada Maré Alta", mainMessage.subject());
    assertTrue(mainMessage.body().contains("Desconto: R$ 37,48"));
    assertTrue(mainMessage.body().contains("Total: R$ 212,42"));
    assertEquals("SENT", mainMessage.status());
    assertEquals("EMAIL", archiveCopy.channel());
    assertEquals("arquivo@pousadamarealta.com.br", archiveCopy.to());
    assertEquals("[Cópia] Reserva confirmada - Pousada Maré Alta", archiveCopy.subject());
    assertEquals("SENT", archiveCopy.status());
}

